CREATE TABLE `application_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `applicationId` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `at` date NOT NULL,
  `who` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `txt` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `application_logs_applicationId_id_idx` (`applicationId`,`id`),
  CONSTRAINT `application_logs_applicationId_fkey` FOREIGN KEY (`applicationId`) REFERENCES `applications` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=896 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
