/*!40000 ALTER TABLE `application_logs` ENABLE KEYS */;
DROP TABLE IF EXISTS `applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `applications` (
  `id` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `product` enum('DDL','HN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `year` int NOT NULL,
  `site` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pm` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `channel` enum('DIRECT','DISTRIBUTION') COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `moveIn` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL,
  `installer` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `managerName` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `managerPhone` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `qty` int NOT NULL,
  `region` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
