/*!40000 ALTER TABLE `external_visits` ENABLE KEYS */;
DROP TABLE IF EXISTS `notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notifications` (
  `id` int NOT NULL AUTO_INCREMENT,
  `applicationId` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `channel` enum('MAIL','SMS') COLLATE utf8mb4_unicode_ci NOT NULL,
  `txt` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `at` date NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `notifications_applicationId_id_idx` (`applicationId`,`id`),
  CONSTRAINT `notifications_applicationId_fkey` FOREIGN KEY (`applicationId`) REFERENCES `applications` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=690 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `notifications` DISABLE KEYS */;
